#pragma once
// Timing/easing ported from Android RpeConvert.java and ChartConvert.java.
#include <algorithm>
#include <array>
#include <cmath>
#include <functional>
#include <stdexcept>
#include <vector>
namespace phimod::rpe {
constexpr double pi=3.14159265358979323846;
inline double bounce(double t){if(t<1/2.75)return 7.5625*t*t;if(t<2/2.75){t-=1.5/2.75;return 7.5625*t*t+.75;}if(t<2.5/2.75){t-=2.25/2.75;return 7.5625*t*t+.9375;}t-=2.625/2.75;return 7.5625*t*t+.984375;}
inline double legacyEase(int k,double t){t=std::clamp(t,0.,1.);switch(k){case 0:return 1;case 1:return t;case 2:return sin(t*pi/2);case 3:return 1-cos(t*pi/2);case 4:return 1-(1-t)*(1-t);case 5:return t*t;case 6:return (1-cos(t*pi))/2;case 7:return t<.5?2*t*t:1-pow(-2*t+2,2)/2;case 8:return 1-pow(1-t,3);case 9:return t*t*t;case 10:return 1-pow(1-t,4);case 11:return pow(t,4);case 12:return t<.5?4*t*t*t:1-pow(-2*t+2,3)/2;case 13:return t<.5?8*pow(t,4):1-pow(-2*t+2,4)/2;case 14:return 1-pow(1-t,5);case 15:return pow(t,5);case 16:return t==1?1:1-pow(2,-10*t);case 17:return t==0?0:pow(2,10*t-10);case 18:return sqrt(1-pow(t-1,2));case 19:return 1-sqrt(1-t*t);case 20:return 1+2.70158*pow(t-1,3)+1.70158*pow(t-1,2);case 21:return 2.70158*t*t*t-1.70158*t*t;case 22:return t<.5?16*pow(t,5):1-pow(-2*t+2,5)/2;case 23:return t==0?0:t==1?1:t<.5?pow(2,20*t-10)/2:(2-pow(2,-20*t+10))/2;case 24:return t<.5?(1-sqrt(1-4*t*t))/2:(sqrt(1-pow(-2*t+2,2))+1)/2;case 25:return t<.5?pow(2*t,2)*((2.5949095+1)*2*t-2.5949095)/2:(pow(2*t-2,2)*((2.5949095+1)*(2*t-2)+2.5949095)+2)/2;case 26:return t==0?0:t==1?1:pow(2,-10*t)*sin((10*t-.75)*2*pi/3)+1;case 27:return t==0?0:t==1?1:-pow(2,10*t-10)*sin((10*t-10.75)*2*pi/3);case 28:return bounce(t);case 29:return 1-bounce(1-t);default:return t;}}
inline double ease(int k,double t){t=std::clamp(t,0.,1.);if(k<=1)return t;if(k>=2&&k<=21)return legacyEase(k,t);if(k>=22&&k<=25)return legacyEase(k+2,t);if(k==26)return bounce(t);if(k==27)return 1-bounce(1-t);if(k==28)return t<.5?(1-bounce(1-2*t))/2:(1+bounce(2*t-1))/2;if(k==29)return t==0?0:t==1?1:t<.5?-(pow(2,20*t-10)*sin((20*t-11.125)*2*pi/4.5))/2:pow(2,-20*t+10)*sin((20*t-11.125)*2*pi/4.5)/2+1;return t;}
struct Tempo{std::vector<double>beats,times,bpms;double factor=1;double seconds(double beat)const{if(beats.empty())throw std::invalid_argument("Missing BPM");auto it=std::upper_bound(beats.begin(),beats.end(),beat);size_t i=it==beats.begin()?0:size_t(it-beats.begin()-1);return factor*(times[i]+(beat-beats[i])*60/bpms[i]);}};
inline double cubic(double t,double a,double b){return 3*(1-t)*(1-t)*t*a+3*(1-t)*t*t*b+t*t*t;}
struct Event{double s=0,e=0,a=0,b=0,left=0,right=1;int easing=1;bool bezier=false;std::array<double,4>points{};
 double value(double t)const{if(a==b)return a;if(e<=s||t>=e)return b;if(t<=s)return a;double q=(t-s)/(e-s);if(bezier){double lo=0,hi=1;for(int i=0;i<20;++i){double m=(lo+hi)/2;if(cubic(m,points[0],points[2])<q)lo=m;else hi=m;}q=cubic((lo+hi)/2,points[1],points[3]);}else{double l=std::clamp(left,0.,1.),r=std::clamp(right,0.,1.);if(easing<=1||l>=r)q=ease(easing,q);else{double x=ease(easing,l),y=ease(easing,r);q=fabs(y-x)<1e-12?q:(ease(easing,l+(r-l)*q)-x)/(y-x);}}return a+(b-a)*q;}};
struct Track{std::vector<Event>events;double fallback=0;double value(double t)const{auto it=std::upper_bound(events.begin(),events.end(),t,[](double v,const Event&e){return v<e.s;});return it==events.begin()?fallback:(--it)->value(t);}};
struct Line{std::array<std::vector<Track>,5>layers;int parent=-1;bool rotateParent=false;double value(int k,double t)const{double v=0;for(const auto&tr:layers[k])v+=tr.value(t);return v;}};
inline std::array<double,3>pose(const std::vector<Line>&lines,int index,double t,std::vector<bool>&seen){if(index<0||size_t(index)>=lines.size())throw std::invalid_argument("Invalid RPE parent");if(seen[index])throw std::invalid_argument("RPE parent cycle");seen[index]=true;const auto&l=lines[index];double x=l.value(0,t),y=l.value(1,t),r=-l.value(2,t);if(l.parent>=0){auto p=pose(lines,l.parent,t,seen);double radians=p[2]*pi/180,ratio=1350./(900.*16/9);double xx=x*cos(radians)-y*ratio*sin(radians);y=x/ratio*sin(radians)+y*cos(radians);x=xx+p[0];y+=p[1];if(l.rotateParent)r+=p[2];}seen[index]=false;return {x,y,r};}
using Linear=std::array<double,6>;
inline void subdivide(std::vector<Linear>&out,const std::function<std::array<double,2>(double)>&fn,double s,double e,std::array<double,2>a,std::array<double,2>b,double tolerance,int depth=0){if(e<=s)return;double mid=(s+e)/2;auto m=fn(mid);double error=0;for(double q:{.25,.5,.75}){auto v=fn(s+(e-s)*q);for(size_t i=0;i<2;++i)error=std::max(error,fabs(v[i]-(a[i]+(b[i]-a[i])*q)));}if(depth<14&&e-s>.001&&error>tolerance){subdivide(out,fn,s,mid,a,m,tolerance,depth+1);subdivide(out,fn,mid,e,m,b,tolerance,depth+1);return;}if(out.size()>=2000000)throw std::invalid_argument("Too many RPE events");out.push_back({s*64,e*64,a[0],b[0],a[1],b[1]});}
}
